#include <locale>
#include <iostream>
int main() {
    try {
        // Construct a locale explicitly with the 'POSIX' locale name
        std::locale posix_locale("POSIX");
        // Use the locale to imbue a stream
        std::cout.imbue(posix_locale);
        std::cout << "Locale set to POSIX" << std::endl;
    } catch (const std::runtime_error& e) {
        std::cerr << "Error creating locale: " << e.what() << std::endl;
    }
    return 0;
}
